/** Synthetic neutral regression-only work. Not shipped course material. */
export function syntheticAdvancedAssessmentPack(){const p=emptyAdvancedAssessmentPack('synthetic-assessment');p.title='Synthetic reasoning and oral assessment';p.description='Review illustrative stepwise reasoning and communication.';p.misconceptions=[{id:'operation',title:'Operation interpretation',explanation:'An authored response pattern for human discussion, not a diagnosis.'}];p.variants=[{id:'a',title:'Variant A',questions:[{kind:'math',id:'math',prompt:'Explain a two-step illustrative calculation.',steps:[{id:'first',prompt:'Combine two equal groups of two.',expected:{kind:'number',value:4,tolerance:0},misconceptions:[{misconceptionId:'operation',accepted:['2']}]},{id:'second',prompt:'Name the operation used.',expected:{kind:'text',accepted:['addition']},misconceptions:[]}]},{kind:'oral',id:'oral',prompt:'Explain the reasoning in your own words.'}]},{id:'b',title:'Variant B',questions:[{kind:'math',id:'math',prompt:'Explain an alternative illustrative calculation.',steps:[{id:'first',prompt:'Combine two equal groups of three.',expected:{kind:'number',value:6,tolerance:0},misconceptions:[]}]},{kind:'oral',id:'oral',prompt:'Describe an alternative approach aloud.'}]}];return parseAdvancedAssessmentPack(p);}
